css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; }
.loader .pot { position: absolute; left: 20%; right: 20%; bottom: 4%; height: 56%; border-radius: 8px 8px 22% 22%; background: linear-gradient(90deg, color-mix(in srgb, #fff 22%, var(--accent)), var(--accent) 60%, color-mix(in srgb, #000 22%, var(--accent))); }
.loader .cream { position: absolute; left: 24%; right: 24%; bottom: 8%; height: 32%; border-radius: 4px 4px 20% 20%; background: var(--accent-2); animation: churn-slosh calc(var(--loader-speed) * .9) ease-in-out infinite; }
.loader .plunger { position: absolute; left: 46%; top: 2%; width: 8%; height: 62%; border-radius: 3px; background: linear-gradient(#e2e8f0, #94a3b8); animation: churn-push calc(var(--loader-speed) * .9) ease-in-out infinite; }
.loader .plunger::after { content: ''; position: absolute; left: -110%; top: 88%; width: 320%; height: 10%; border-radius: 3px; background: #94a3b8; }
.loader i { position: absolute; width: 7%; height: 7%; border-radius: 50%; background: var(--accent-2); opacity: 0; animation: churn-splash calc(var(--loader-speed) * .9) ease-out infinite; }
.loader i:nth-of-type(1) { left: 26%; bottom: 40%; --dx: -60%; }
.loader i:nth-of-type(2) { right: 26%; bottom: 40%; --dx: 60%; animation-delay: calc(var(--loader-speed) * .45); }
@keyframes churn-push { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(16%); } }
@keyframes churn-slosh { 0%, 100% { transform: scaleY(1) skewX(0deg); } 50% { transform: scaleY(1.08) skewX(3deg); } }
@keyframes churn-splash { 0%, 40% { opacity: 0; transform: translate(0, 0) scale(.5); } 55% { opacity: 1; transform: translate(calc(var(--dx, 0%) * .5), -60%) scale(1); } 100% { opacity: 0; transform: translate(var(--dx, 0%), -10%) scale(.6); } }
